p5.disableFriendlyErrors = true;

const ColorPalette = Object.freeze({
	  "color1": "#ffbad6",
  	"color2": "#1483ff",
  	"color3": "#ffe012"
});

let blurVs = `
precision mediump float;

attribute vec3 aPosition;
attribute vec2 aTexCoord;
uniform mat4 uProjectionMatrix;
uniform mat4 uModelViewMatrix;

varying vec2 vTexCoord;

void main() { 
  vec3 uPosition = aPosition;
  vec4 positionVec4 = vec4(uPosition, 1.0);

  gl_Position = uProjectionMatrix * uModelViewMatrix * positionVec4;//positionVec4;
  vTexCoord = aTexCoord;
}
`;

let blurFs = `
#ifdef GL_ES
precision mediump float;
#endif
varying vec2 vTexCoord;

uniform sampler2D baseGraphics;
uniform float time;
uniform vec2 resolution;
uniform float gCoefficients[65];
uniform bool isVertical;

#define TABLE_SIZE 65

vec3 color;

void main() {
    // vec2 uv = vec2(vTexCoord.x, 1.0 - vTexCoord.y);
	vec2 uv = vTexCoord;
	vec4 returnColor = vec4(0.0);
	for(int i = 0; i < TABLE_SIZE; i++){
		vec2 offset = vec2(0.0);
		if(isVertical)
		{
			offset.x = 0.0;
			offset.y = float(i) - float(TABLE_SIZE - 1) / 2.0;
		}
		else
		{
			offset.x = float(i) - float(TABLE_SIZE - 1) / 2.0;
			offset.y = 0.0;
		}
		vec2 inverseResolution = 1.0 / resolution;
		vec4 texColor = texture2D(baseGraphics, uv + offset * inverseResolution);
		returnColor += texColor * gCoefficients[i];
	}
	gl_FragColor = returnColor;
}
`;

let bloomVs = `
precision mediump float;

attribute vec3 aPosition;
attribute vec2 aTexCoord;
uniform mat4 uProjectionMatrix;
uniform mat4 uModelViewMatrix;

varying vec2 vTexCoord;

void main() { 
  vec3 uPosition = aPosition;
  vec4 positionVec4 = vec4(uPosition, 1.0);

  gl_Position = uProjectionMatrix * uModelViewMatrix * positionVec4;//positionVec4;
  vTexCoord = aTexCoord;
}
`;

let bloomFs = `
#ifdef GL_ES
precision mediump float;
#endif
varying vec2 vTexCoord;

uniform sampler2D baseTex;
uniform sampler2D tex;
uniform float time;
uniform vec2 resolution;
uniform float bloomStrength;

vec3 color;

void main() {
    // vec2 uv = vec2(vTexCoord.x, 1.0 - vTexCoord.y);
	vec2 uv = vTexCoord;
	vec4 texColor = texture2D(tex, uv);
	vec4 baseTexColor = texture2D(baseTex, uv);

	gl_FragColor = texColor * bloomStrength + baseTexColor;
}
`;

let baseGraphics;
let pass1, pass2, pass3;
let pass1Shader, pass2Shader, pass3Shader;
let gCoefficients = [];

let bigStars = [];

function setup() {
// 	createCanvas(windowWidth, windowHeight);
	createCanvas(920, 690, WEBGL);
	background(0);

	let cols = [
		color(ColorPalette.color1),
		color(ColorPalette.color2),
		color(ColorPalette.color3),
	];

	for(let i = 0; i < 3; i++){
		let a = (TWO_PI / 3) * i;
		bigStars.push(new BigStar(400, a, cols[i]));
	}

	gl = this._renderer.GL;
	gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA);
	gl.disable(gl.DEPTH_TEST);

	baseGraphics = createGraphics(width, height, WEBGL);
	pass1 = createGraphics(width, height, WEBGL);
	pass2 = createGraphics(width, height, WEBGL);
	pass3 = createGraphics(width, height, WEBGL);

	pass1Shader = pass1.createShader(blurVs, blurFs);
	pass2Shader = pass2.createShader(blurVs, blurFs);
	pass3Shader = pass3.createShader(bloomVs, bloomFs);

	pass1.noStroke();
	pass2.noStroke();
	pass3.noStroke();

	setupGaussianCoefficients(10.0, 64.0);
}

function draw() {
	background(0);
	baseGraphics.clear();

	for(let i = bigStars.length-1; i >= 0; i--){
		bigStars[i].update();
		bigStars[i].display(baseGraphics);
	}

	pass1.clear();
	pass1.shader(pass1Shader);
	pass1Shader.setUniform('baseGraphics', baseGraphics);
	pass1Shader.setUniform("resolution", [baseGraphics.width, baseGraphics.height]);
	pass1Shader.setUniform("time", frameCount*0.04);
	pass1Shader.setUniform("gCoefficients", gCoefficients);
	pass1Shader.setUniform("isVertical", false);
	pass1.rectMode(CENTER);
	pass1.rect(0, 0, width, height);

	pass2.clear();
	pass2.shader(pass2Shader);
	pass2Shader.setUniform('baseGraphics', pass1);
	pass2Shader.setUniform("resolution", [pass1.width, pass1.height]);
	pass2Shader.setUniform("time", frameCount*0.04);
	pass2Shader.setUniform("gCoefficients", gCoefficients);
	pass2Shader.setUniform("isVertical", true);
	pass2.rectMode(CENTER);
	pass2.rect(0, 0, width, height);

	pass3.clear();
	pass3.shader(pass3Shader);
	pass3Shader.setUniform('tex', pass2);
	pass3Shader.setUniform('baseTex', baseGraphics);
	pass3Shader.setUniform("resolution", [baseGraphics.width, baseGraphics.height]);
	pass3Shader.setUniform("time", frameCount*0.04);
	pass3Shader.setUniform("bloomStrength", 1.8);
	pass3.rectMode(CENTER);
	pass3.rect(0, 0, width, height);

	imageMode(CENTER);
	image(pass3, 0, 0);
}

function BigStar(radius, angle, col){
	this.standardPos = createVector(0.0, 0.0, -400.0);
	this.radius = radius;
	this.maxRadius = radius;
	this.angle = angle;
	this.col = col;
	this.pos = createVector(radius * cos(angle), height, radius * sin(angle));
	this.pos.add(this.standardPos);
	this.aVel = 0.05;
	this.yVel = -3;
	let len = 80;
	this.resolution = [len, len];
	this.smallStars = [];

	this.update = function(){
		this.angle += this.aVel;
		this.radius = this.maxRadius * map(sin(frameCount*0.01), -1, 1, 0.2, 1);
		this.pos.y += this.yVel;
		this.pos.x = this.radius * cos(this.angle);
		this.pos.z = this.radius * sin(this.angle);
		this.pos.add(this.standardPos);

		if(this.pos.y < -height){
			this.pos.y = height;
		}

		if(random(1) > 0.7){
			this.smallStars.push(new SmallStar(this.radius, this.pos.y, this.angle, (random(1) > 0.5)));
		}
	}

	this.display = function(gr){
		gr.push();
		gr.translate(this.pos.x, this.pos.y, this.pos.z);
		gr.rotateY(-this.angle + HALF_PI);
		gr.fill(this.col, 18);
		gr.stroke(this.col, 255);
		gr.strokeWeight(5);
		gr.beginShape();
		for(let i = 0; i < 10; i++){
			var a = (TWO_PI / 10) * i - this.angle * 1.2;
			if(i % 2 == 0){
				let x = this.resolution[0] * cos(a);
				let y = this.resolution[1] * sin(a);
				gr.vertex(x, y);
			}else{
				var x = this.resolution[0] * 0.5 * cos(a);
				var y = this.resolution[1] * 0.5 * sin(a);
				gr.vertex(x, y);
			}
		}
		gr.endShape(CLOSE);
		gr.pop();

		for(let i = this.smallStars.length-1; i >= 0; i--){
			this.smallStars[i].update();
			this.smallStars[i].display(gr);
			if(this.smallStars[i].isFinished()){
				this.smallStars.splice(i, 1);
			}
		}
	}
}

function SmallStar(radius, h, angle, isFill){
	this.standardPos = createVector(0.0, 0.0, -400.0);
	this.radius = radius;
	this.maxRadius = radius;
	this.angle = angle;
	this.hue = random(360);
	this.pos = createVector(radius * cos(angle), h, radius * sin(angle));
	this.pos.add(this.standardPos);
	this.aVel = random(-0.005, 0.005);
	this.yVel = random(-0.1, 0.1);
	this.isFill = isFill;
	this.alphaCoef = 0.0;
	var len = random(20, 40);
	this.resolution = [len, len];

	this.update = function(){
		this.angle += this.aVel;
		this.pos.y += this.yVel;
		this.pos.x = this.radius * cos(this.angle);
		this.pos.z = this.radius * sin(this.angle);
		this.pos.add(this.standardPos);
		this.alphaCoef += 0.04;
	}

	this.display = function(gr){
		gr.push();
		gr.translate(this.pos.x, this.pos.y, this.pos.z);
		gr.rotateY(-this.angle + HALF_PI);
		gr.colorMode(HSB, 360, 100, 100, 100);
		if(this.isFill){
			gr.fill(this.hue, 0, 100, 18 * sin(this.alphaCoef));
		}else{
			gr.noFill();
		}
		gr.stroke(this.hue, 100, 100, 360 * sin(this.alphaCoef));
		gr.strokeWeight(5);
		gr.beginShape();
		for(let i = 0; i < 10; i++){
			var a = (TWO_PI / 10) * i - this.angle * 5.2;
			if(i % 2 == 0){
				var x = this.resolution[0] * cos(a);
				var y = this.resolution[1] * sin(a);
				gr.vertex(x, y);
			}else{
				var x = this.resolution[0] * 0.5 * cos(a);
				var y = this.resolution[1] * 0.5 * sin(a);
				gr.vertex(x, y);
			}
		}
		gr.endShape(CLOSE);
		gr.pop();
	}

	this.isFinished = function(){
		if(this.alphaCoef > PI){
			//return true;
		}

		return false;
	}
}

function setupGaussianCoefficients(range, count){
	gCoefficients.splice(0, gCoefficients.length);
	let totalRange = range * 2.0;
	let startRange = -range;
	let incrementValue = totalRange / count;
	let totalValue = 0.0;

	for(let i = startRange; i <= range; i+=incrementValue){
		let value = exp(-(i * i) / totalRange);
		totalValue += value;
		gCoefficients.push(value);
	}

	for(let i = 0; i < gCoefficients.length; i++){
		gCoefficients[i] /= totalValue;
	}
}

let lapse = 0;    // mouse timer
function mousePressed(){
// prevents mouse press from registering twice
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() +
    ".jpg");
    lapse = millis();
  }
}

